mapper.select:
SELECT
	bc.BOOKSET_ID booksetId, /**账务明细（当前表）.账套代码 **/
	bc.BOK_DETAIL_ID bokDetailId, /**账务明细（当前表）.账务明细代码**/
	bc.BUSI_ID busiId, /**账套明细代码.业务明细代码**/
	c.BUSI_DETAIL_TYPE busiDetailType,/**账套明细代码.业务明细类型**/
	bc.TABLE_ID tableId, /**账务明细（当前表）.场景代码**/
	bc.SUBJECT_NO subjectNo, /**账务明细（当前表）.科目号**/
	c.INV_AIM invAim,/**账套明细代码.投资目的**/
	bc.O_CCY oCcy, /**账务明细（当前表）.原币**/
	bc.CD_FLAG cdFlag, /**账务明细（当前表）.借贷方向 as 借贷方向**/
	bc.BAL_FLAG_HAPPEN_DATE balFlagHappenDate, /**账务明细（当前表）.余额方向（发生日） as 余额方向**/
	bc.O_HAPPEN_AMT oHappenAmt, /**账务明细（当前表）.原币发生额（发生日） as 原币发生额**/
	bc.O_AMT_HAPPEN_DATE oAmtHappenDate, /**账务明细（当前表）.原币余额（发生日） as 科目余额**/
	bc.NUM_AMT_HAPPEN_DATE numAmtHappenDate, /**账务明细（当前表）.数量余额（发生日）as 数量余额**/
	bc.B_CCY bCcy, /**账务明细（当前表）.本位币**/
	bc.B_HAPPEN_AMT bHappenAmt, /**账务明细（当前表）.本币发生额（发生日） as 本币科目余额**/
	bc.B_AMT_HAPPEN_DATE bAmtHappenDate, /**账务明细（当前表）.本币余额（发生日） as 本币科目余额**/
	bc.HAPPEN_DATE happenDate, /**账务明细（当前表）.发生日**/
	bc.BASE_SUBJECT_NATURE baseSubjectNature, /**账务明细（当前表）.基础科目性质**/
	bc.DETAIL_SUBJECT_NO detailSubjectNo /**账务明细（当前表）.四级科目号**/
FROM
	BOK_BOOKDETAIL_CURRENT bc
	INNER JOIN BOK_DETAIL_ID c
		ON bc.BOOKSET_ID = c.BOOKSET_ID AND bc.BOK_DETAIL_ID = c.BOK_DETAIL_ID
WHERE
	/**账务明细（当前表）.账套代码 = 参数.账套代码 **/
	bc.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
	/**AND 账务明细（当前表）.发生日 大于等于 参数.开始日**/
	and bc.HAPPEN_DATE  >=  #{startHappenDate,jdbcType=VARCHAR}
	/**AND 账务明细（当前表）.发生日 小于等于 参数.结束日**/
	and bc.HAPPEN_DATE  <=  #{endHappenDate,jdbcType=VARCHAR}
	/**AND 账务明细（当前表）.入账日  小于等于 参数.入账日**/
	and bc.BOOK_DATE  <=  #{bookDate,jdbcType=VARCHAR}
	/**AND 账务明细（当前表）.基础科目性质 IN  (参数.list基础科目性质）**/

		AND bc.BASE_SUBJECT_NATURE IN

			#{baseSubjectNature}


	/**AND 账务明细（当前表）.场景代码 IN  (参数.list场景代码）**/

		AND bc.TABLE_ID IN

			#{tableId}



		AND bc.BOK_DETAIL_ID = #{bokDetailId}

	/**AND 账务明细（当前表）.借贷方向 = 参数.借贷方向**/
	and bc.CD_FLAG = #{cdFlag,jdbcType=VARCHAR}
	/**AND 账务明细（当前表）.优先级  小于 参数.优先级**/
    and bc.TASK_ID  <  #{taskId}

		AND bc.SUBJECT_NO = #{subjectNo}

/**账务明细（当前表）.BOOK_ORDER**/
order by bc.book_order
